# A fixed-capacity, least-recently-used cache.
class LRUCache
  def initialize(capacity)
    unless capacity.is_a?(Integer) && capacity.positive?
      raise ArgumentError, "capacity must be a positive integer"
    end

    @capacity = capacity
    @entries = {}
  end

  # Returns nil on a miss. Accessing an entry makes it most recently used.
  def get(key)
    return nil unless @entries.key?(key)

    value = @entries.delete(key)
    @entries[key] = value
    value
  end

  # Inserts or updates an entry, evicting the least recently used if needed.
  def put(key, value)
    @entries.delete(key)
    @entries[key] = value
    @entries.shift if @entries.size > @capacity
    value
  end
end
